namespace {baseNamespace}\Wf\Util;

use GuzzleHttp\Client;
use GuzzleHttp\ClientInterface;
use GuzzleHttp\Exception\GuzzleException;
use JsonException;
use {baseNamespace}\Wf\Config\WfConfig;
use {baseNamespace}\Wf\Model\Exception\WfErrorCode;
use {baseNamespace}\Wf\Model\Exception\WfException;
use {baseNamespace}\Wf\Model\WfModel;
use {baseNamespace}\Wf\Signer\WfSigner;

/** 负责请求签名、HTTPS 发送和响应强制验签。 */
final class WfHttpClient
{
    private WfConfig $config;
    private WfSigner $signer;
    private ClientInterface $httpClient;

    public function __construct(
        WfConfig $config,
        ?WfSigner $signer = null,
        ?ClientInterface $httpClient = null
    ) {
        $this->assertHttpsEndpoint($config->getBaseUrl());
        $this->config = $config;
        $this->signer = $signer ?? new WfSigner($config);
        $this->httpClient = $httpClient ?? new Client([
            'connect_timeout' => $config->getConnectTimeout(),
            'timeout' => $config->getReadTimeout(),
            'allow_redirects' => false,
            'http_errors' => false,
        ]);
    }

    public function getConfig(): WfConfig
    {
        return $this->config;
    }

    public function getSigner(): WfSigner
    {
        return $this->signer;
    }

    public function sendPostRequest(string $apiPath, string $requestBody): string
    {
        $this->assertApiPath($apiPath);
        $requestTime = $this->signer->getCurrentTimestamp();
        $signature = $this->signer->generateSignature($apiPath, $requestTime, $requestBody);

        try {
            $response = $this->httpClient->request('POST', $this->config->getBaseUrl() . $apiPath, [
                'headers' => [
                    'Content-Type' => 'application/json; charset=UTF-8',
                    'Client-Id' => $this->config->getClientId(),
                    'Request-Time' => $requestTime,
                    'Signature' => sprintf('algorithm=RSA256, keyVersion=2, signature=%s', $signature),
                ],
                'body' => $requestBody,
            ]);
        } catch (GuzzleException $exception) {
            throw new WfException(WfErrorCode::HTTP_REQUEST_FAILED, 'WorldFirst HTTP request failed.', $exception);
        }

        $statusCode = $response->getStatusCode();
        $responseBody = (string) $response->getBody();
        if ($statusCode !== 200) {
            throw new WfException(
                WfErrorCode::HTTP_REQUEST_FAILED,
                sprintf('WorldFirst returned HTTP status %d.', $statusCode)
            );
        }

        $signatureHeader = $response->getHeaderLine('Signature');
        $responseTime = $response->getHeaderLine('Response-Time');
        if ($signatureHeader === '' || $responseTime === '') {
            throw new WfException(
                WfErrorCode::INVALID_SIGNATURE,
                'WorldFirst response is missing Signature or Response-Time.'
            );
        }
        if (!$this->signer->verifySignature($signatureHeader, $apiPath, $responseTime, $responseBody)) {
            throw new WfException(WfErrorCode::INVALID_SIGNATURE, 'WorldFirst response signature verification failed.');
        }

        return $responseBody;
    }

    public function postJson(string $apiPath, WfModel|array $request): array
    {
        $payload = $request instanceof WfModel ? $request->toArray() : $request;

        try {
            $requestBody = json_encode($payload, JSON_THROW_ON_ERROR | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
            $responseBody = $this->sendPostRequest($apiPath, $requestBody);
            $decoded = json_decode($responseBody, true, 512, JSON_THROW_ON_ERROR);
        } catch (JsonException $exception) {
            throw new WfException(WfErrorCode::INVALID_RESPONSE_FORMAT, 'Invalid WorldFirst JSON payload.', $exception);
        }

        if (!is_array($decoded)) {
            throw new WfException(WfErrorCode::INVALID_RESPONSE_FORMAT, 'WorldFirst response must be a JSON object.');
        }

        return $decoded;
    }

    private function assertHttpsEndpoint(string $baseUrl): void
    {
        $parts = parse_url($baseUrl);
        if (
            $parts === false
            || strtolower($parts['scheme'] ?? '') !== 'https'
            || !isset($parts['host'])
            || isset($parts['user'])
            || isset($parts['pass'])
            || isset($parts['query'])
            || isset($parts['fragment'])
        ) {
            throw new WfException(WfErrorCode::PARAM_ILLEGAL, 'WorldFirst base URL must be a valid HTTPS endpoint.');
        }
    }

    private function assertApiPath(string $apiPath): void
    {
        if ($apiPath === '' || $apiPath[0] !== '/' || str_contains($apiPath, '..') || str_contains($apiPath, '?')) {
            throw new WfException(WfErrorCode::PARAM_ILLEGAL, 'Invalid WorldFirst API path.');
        }
    }
}
